),
ANCESTORS AS (
  SELECT CONNECT_BY_ROOT MNU_ID AS MNU_ID, MNU_ID AS ANC_MNU_ID
    FROM SCM_MGR.SCM_ADM_MNU_M
 CONNECT BY NOCYCLE PRIOR UPPR_MNU_ID = MNU_ID
),
GRANT_MNUS AS (
  SELECT DISTINCT A.GR, AN.ANC_MNU_ID AS MNU_ID
    FROM ASIS_GRANT A
    JOIN ANCESTORS AN ON AN.MNU_ID = A.MNU
)
SELECT G.GR AS USER_GR_ID, G.MNU_ID
  FROM GRANT_MNUS G
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_USER_GR_MNU_MPG_M P
                    WHERE P.USER_GR_ID = G.GR AND P.MNU_ID = G.MNU_ID)
 ORDER BY 1, 2;

