SELECT A.GR AS USER_GR_ID, B.MNU_ID, COUNT(*) AS GAP_BTN_CNT
  FROM ASIS_GRANT A
  JOIN SCM_MGR.SCM_ADM_MNU_BTN_MPG_M B ON B.MNU_ID = A.MNU
 WHERE (   B.MNU_BTN_CD LIKE 'SEARCH%' OR B.MNU_BTN_CD IN ('EXCEL','FILTER','SORT','COLUMN_SETUP','MEASURE_SELECT','TITLE','SPREAD_TITLE_DATE','SP_VER','TEXTBOX','LOAD_PERCENT','VERSION_MGMT','VERSION_MGT')
             OR (A.C = 'Y' AND B.MNU_BTN_CD IN ('INSERT','NEW'))
             OR (A.D = 'Y' AND B.MNU_BTN_CD = 'DELETE')
             OR (A.U = 'Y' AND B.MNU_BTN_CD NOT LIKE 'SEARCH%'
                 AND B.MNU_BTN_CD NOT IN ('EXCEL','FILTER','SORT','COLUMN_SETUP','MEASURE_SELECT','TITLE','SPREAD_TITLE_DATE','SP_VER','TEXTBOX','LOAD_PERCENT','VERSION_MGMT','VERSION_MGT','INSERT','NEW','DELETE')))
   AND NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M P
                    WHERE P.USER_GR_ID = A.GR AND P.MNU_ID = B.MNU_ID
                      AND P.SHT_NM = B.SHT_NM AND P.MNU_BTN_CD = B.MNU_BTN_CD)
 GROUP BY A.GR, B.MNU_ID ORDER BY 1, 2;

