SELECT A.GR AS USER_GR_ID, A.MNU AS ASIS_PROGRAM_ID
  FROM ASIS_GRANT A
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_M M WHERE M.MNU_ID = A.MNU)
 ORDER BY 1, 2;

