SELECT DISTINCT B.MNU_ID, B.SHT_NM, B.MNU_BTN_CD
  FROM ASIS_GRANT A
  JOIN SCM_MGR.SCM_ADM_MNU_BTN_MPG_M B ON B.MNU_ID = A.MNU
 WHERE B.API_ID IS NULL AND B.USE_YN = 'Y'
 ORDER BY 1, 2, 3;

-- [진단 5] SYS0002/SYS0014 접근 가능 그룹 현황 (참고)
SELECT USER_GR_ID, MNU_ID FROM SCM_MGR.SCM_ADM_USER_GR_MNU_MPG_M
 WHERE MNU_ID IN ('SYS0002','SYS0014') ORDER BY 2, 1;
